import { GaugeKind } from "../custom-metrics/index.js";
export interface CustomMetric<TLabel extends string = "default"> {
    /**
     * The name of the custom metric.
     * This should be a descriptive name that identifies the metric.
     * For example, "user_login_count" or "api_response_time".
     */
    name: string;
    /**
     * The value of the custom metric.
     * Starts with 0 and can be incremented or decremented based on the metric type.
     * For example, if the metric is a counter for user logins, this value would
     * represent the total number of user logins counted so far.
     * If the metric is a gauge for memory usage, this value would represent the current memory
     * usage in bytes or megabytes.
     */
    value: Record<string, number>;
    /**
     * Description for the custom metric.
     * This can be used to provide additional context about what the metric represents.
     * For example, "Number of user logins in the last hour" or "Average response time for API requests".
     */
    description?: string;
    /**
     * The type of the custom metric.
     * - "counter" is used for metrics that are incremented, such as the number of requests.
     * - "gauge" is used for metrics that can go up and down, such as memory usage.
     * - "summary" is used for distributions, such as request latency. Quantiles are
     *   computed in-process over each flush window, so raw observations never leave
     *   the agent.
     */
    type: "counter" | "gauge" | "summary";
    /**
     * Optional labels for the custom metric.
     * Labels are key-value pairs that can be used to add additional context to the metric.
     * For example, you might use labels to indicate the environment (e.g., "production", "development") or the service (e.g., "user-service", "order-service").
     */
    labels?: TLabel[];
    /**
     * Optional kind for gauge metrics.
     * This can be "additive", "ratio", or "peak".
     * - "additive": A gauge value will be summed up when multiple instances report values.
     * - "ratio": A gauge value represents a ratio and should be averaged across instances.
     * - "peak": A gauge value represents a peak measurement and the highest value should be reported.
     */
    kind?: GaugeKind;
    /**
     * Optional tags for the custom metric.
     * Tags are key-value pairs that can be used to add additional context to the metric.
     * For example, you might use tags to indicate the environment (e.g., "production", "development") or the service (e.g., "user-service", "order-service").
     */
    tags?: Record<string, string>;
    /**
     * Represents when the custom metric was recorded/updated.
     * This is a Unix timestamp in milliseconds that indicates the time when the metric was last updated.
     */
    lastUpdated?: number;
    /**
     * How much a counter rose since the previous flush, per label.
     *
     * `value` is cumulative for the life of the process, so summing it across
     * reports double counts. This is the additive quantity: summing it over a
     * window gives the real total, and it is unaffected by a process restarting
     * and resetting `value` back to zero.
     *
     * Counters only - a gauge reading is absolute and has no meaningful increase.
     */
    increase?: Record<string, number>;
    /**
     * Quantiles computed in-process over the observations since the last flush,
     * per label. Summaries only.
     *
     * Because these arrive already computed, combining them across instances can
     * only estimate the true percentile - the exactly-mergeable figures below are
     * what to lean on when that matters.
     */
    p50?: Record<string, number>;
    p95?: Record<string, number>;
    p99?: Record<string, number>;
    /**
     * Observation count and sum behind the quantiles, per label. Summaries only.
     * Both merge exactly, so a mean derived from them holds across any number of
     * reporters.
     */
    observations?: Record<string, number>;
    total?: Record<string, number>;
    /**
     * Largest single observation per label since the last flush. Summaries only.
     * Merges exactly, so the worst case survives being combined.
     */
    maximum?: Record<string, number>;
}
